# Generated by Phase: IMPLEMENT | Feature: EVOL-115
"""Reliability is planned up front (EVOL-115): the design and the contracts the change touches, read at the freeze.

Every `docs/spec/*/design.md` and `contracts/openapi/**.{yaml,yml,json}` the change touches (the tree on disk against
the merge-base with the diff base) is read. Red when:

  (a) unanswered question  in `design.md § Reliability Questions`, a capability row weighted security, availability or
                           both has an RQ cell with no answer or no source (`answer · source`); a weight outside the
                           closed vocabulary (security, availability, both, none) is red. No section, no recognised
                           header or no weighted row → that design is `n/a` with its reason, never an ok note.
  (b) no outage response   an OpenAPI operation declares no response keyed `contracts.outage_status`.
  (c) open sensitive field a schema carrying a non-false `x-sensitive` (anywhere: components, inline, items, allOf)
                           carries none of maxLength, pattern, enum, format, minimum, maximum. The green line counts them.
An unparseable, empty or malformed contract is red with its reason (LAW-08). Nothing to judge → `freeze: n/a`.
Raised ⊆ declared belongs to the contract parity reader, when it lands — not this one.
"""
from __future__ import annotations

import json
import re
from pathlib import Path

from .common import GateFault, clean as _clean, key, parse_yaml
from .digests import changed_paths
from .seal import DEFAULT_SEAL_DIR, _norm_path, vcfg

DESIGN_RE = re.compile(r"docs/spec/[^/]+/design\.md")
CONTRACT_RE = re.compile(r"contracts/openapi/.+\.(?:ya?ml|json)")
METHODS = ("get", "put", "post", "delete", "patch", "head", "options")
CONSTRAINTS = ("maxLength", "pattern", "enum", "format", "minimum", "maximum")
WEIGHTS = ("security", "availability", "both", "none")   # closed (owner RDR «1»): any other word is red
WEIGHTED = ("security", "availability", "both")
BLANK = re.compile(r"^(?:|—|-|–|tbd|todo|\?+|\{\{[^}]*\}\})$", re.I)


def _cells(line: str) -> list[str]:
    return [c.strip() for c in line.strip().strip("|").split("|")]


def _section(text: str, title: str) -> str:
    m = re.search(rf"(?mi)^##\s+{re.escape(title)}\s*$", text or "")
    if not m:
        return ""
    end = re.search(r"(?m)^##\s", text[m.end():])
    return text[m.end(): m.end() + end.start()] if end else text[m.end():]


def _blank(s: str) -> bool:
    return bool(BLANK.match(s.strip().strip("`*_ ").strip()))


def questions(text: str) -> tuple[list[str], int, str]:
    """Clause (a) on one design: (problems, weighted rows judged, why nothing was judged)."""
    if not re.search(r"(?mi)^##\s+Reliability Questions\s*$", text or ""):
        return [], 0, "no `## Reliability Questions` section — nothing to judge"
    problems, header, judged, seen_set = [], None, 0, False
    for line in _section(text, "Reliability Questions").splitlines():
        if not line.strip().startswith("|"):
            header = None
            continue
        cells = _cells(line)
        if header is None:
            header = [c.lower() for c in cells]
            continue
        if all(set(c) <= set(":- ") for c in cells):
            continue
        if "weight" not in header or not any(h.startswith("rq-") for h in header):
            continue   # the mapping table, or any table that is not the question set
        seen_set = True
        row = dict(zip(header, cells))
        cap = row.get(header[0], "?")
        weight = row.get("weight", "").strip().strip("`*_ ").strip().lower()
        if weight not in WEIGHTS:
            problems.append(f"capability `{cap}` carries weight `{row.get('weight', '')}` — the weight is one of {', '.join(WEIGHTS)}")
            continue
        if weight not in WEIGHTED:
            continue
        judged += 1
        for h in header:
            if not h.startswith("rq-"):
                continue
            answer, _, source = row.get(h, "").partition("·")
            if _blank(answer) or _blank(source):
                problems.append(f"capability `{cap}` ({row['weight']}) leaves {h.upper()} without "
                                f"{'an answer' if _blank(answer) else 'a source'} — answer it with a cited source before the freeze")
    if not seen_set:
        return problems, 0, "no question table with a `Weight` and `RQ-…` header under `## Reliability Questions` — nothing to judge"
    return problems, judged, "" if judged else "no capability weighted security, availability or both — nothing to judge"


MAX_DEPTH = 200


def _walk(node, ptr: str = "#"):
    """Every mapping of the document, each object once (a YAML alias is walked once), iteratively (no recursion limit)."""
    seen, todo = set(), [(node, ptr, 0)]
    while todo:
        n, p, d = todo.pop()
        if not isinstance(n, (dict, list)) or id(n) in seen:
            continue
        if d > MAX_DEPTH:
            raise GateFault(f"the contract is nested deeper than {MAX_DEPTH} levels at {p[:120]}… — flatten it with `$ref`")
        seen.add(id(n))
        kids = n.items() if isinstance(n, dict) else enumerate(n)
        if isinstance(n, dict):
            yield p, n
        todo += [(v, f"{p}/{k}", d + 1) for k, v in reversed(list(kids))
                 if isinstance(v, (dict, list)) and id(v) not in seen]   # scalars carry no pointer: no string per leaf


def _sensitive(v) -> bool:
    """Any marker that is not false marks the field (`true`, `"true"`, `1`); `false`, `"false"`, `0`, `""` do not.
    Decided by type, never by `str()`: a stringified aliased list re-expands every alias."""
    if isinstance(v, bool) or v is None:
        return bool(v)
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() not in ("false", "0", "", "no", "off")
    return bool(v)


def contract(doc, outage: str, counted: list | None = None) -> list[str]:
    """Clauses (b) and (c) on one parsed OpenAPI document; `counted` receives the number of sensitive fields."""
    problems = []
    if doc is None or doc == {} or doc == "":
        return ["empty contract — nothing in it declares an operation; write the contract or drop the file"]
    if not isinstance(doc, dict):
        return ["the contract is not a mapping — not an OpenAPI document"]
    paths = doc.get("paths") or {}
    if not isinstance(paths, dict):
        raise GateFault("its `paths` is not a mapping of routes — not an OpenAPI document")
    for path, item in paths.items():
        if not isinstance(item, dict):
            continue
        for meth in METHODS:
            op = item.get(meth)
            if not isinstance(op, dict):
                continue
            responses = op.get("responses") or {}
            if not isinstance(responses, dict):
                raise GateFault(f"{meth.upper()} {path}: its `responses` is not a mapping of statuses — not an OpenAPI document")
            if outage not in {str(k).strip("'\"") for k in responses}:   # the subset parser keeps a key's quotes
                problems.append(f"{meth.upper()} {path} declares no `{outage}` response — say what it returns when a dependency is down")
    marked = 0
    for ptr, node in _walk(doc, "#"):
        if _sensitive(node.get("x-sensitive")):
            marked += 1
            if not any(c in node for c in CONSTRAINTS):
                problems.append(f"sensitive field {ptr} carries no constraint ({', '.join(CONSTRAINTS)}) — bound its input")
    if counted is not None:
        counted.append(marked)
    return problems


def _load(path: Path):
    text = path.read_text(encoding="utf-8", errors="replace")
    if path.suffix == ".json":
        try:
            return json.loads(text)
        except ValueError as e:
            raise GateFault(f"not valid JSON ({e})") from None
    if not text.strip():
        return None
    try:
        return parse_yaml(text)
    except GateFault as e:
        try:
            import yaml  # type: ignore  # noqa: F401
        except ImportError:
            raise GateFault(f"{e} — install PyYAML: the subset parser cannot read lists of mappings") from None
        raise
    except (RecursionError, ValueError, OverflowError) as e:
        raise GateFault(f"not readable YAML ({type(e).__name__})") from None


def check(repo: Path, base: str, branch: str | None = None) -> dict:
    try:
        cfg = vcfg(repo)
    except GateFault:
        cfg = {"dir": DEFAULT_SEAL_DIR}
    changed = sorted(c for c in {_norm_path(c) for c in changed_paths(repo, base, cfg)} if (repo / c).is_file())
    designs = [c for c in changed if DESIGN_RE.fullmatch(c)]
    contracts = [c for c in changed if CONTRACT_RE.fullmatch(c)]
    rows = []
    for d in designs:
        problems, judged, why = questions((repo / d).read_text(encoding="utf-8", errors="replace"))
        note = f"n/a — {why}" if not judged else f"{judged} weighted capabilit{'y' if judged == 1 else 'ies'} answered with a cited source"
        rows.append({"id": d, "ok": not problems, "problems": problems, "note": note, "na": not judged and not problems})
    if contracts:
        try:
            outage = str(key(repo, "contracts.outage_status", required=True))
        except GateFault as e:
            return {"ok": False, "files": designs + contracts, "entries": [], "reason": str(e)}
        for c in contracts:
            counted: list = []
            try:
                problems = contract(_load(repo / c), outage, counted)
            except RecursionError:
                problems = ["cannot be read as a contract — nested too deep for the reader; flatten it with `$ref` so the freeze can judge it"]
            except GateFault as e:
                problems = [f"cannot be read as a contract — {str(e).replace('frontmatter is not valid YAML', 'not valid YAML')}; fix its syntax so the freeze can judge it"]
            n = counted[0] if counted else 0
            rows.append({"id": c, "ok": not problems, "problems": problems,
                         "note": f"every operation declares `{outage}`; {n} sensitive field{'' if n == 1 else 's'} bounded"})
    if not rows:
        return {"ok": True, "files": [], "entries": [], "reason": "no design (docs/spec/*/design.md) and no contract (contracts/openapi/**) in the change — nothing to judge"}
    red = [r for r in rows if not r["ok"]]
    if all(r.get("na") for r in rows):   # nothing judged: n/a with its reason, never the ok note (ADR-EVOL-115 Decision 3)
        return {"ok": True, "na": True, "files": designs, "entries": rows,
                "reason": "nothing judged — " + "; ".join(r["note"][len("n/a — "):] for r in rows)}
    return {"ok": not red, "files": designs + contracts, "entries": rows,
            "reason": f"{len(red)} of {len(rows)} file(s) red" if red else f"{len(rows)} file(s) green — reliability planned up front"}


def render(res: dict) -> str:
    if not res.get("entries"):
        return _clean(f"freeze: {'n/a' if res['ok'] else 'RED'} — {res['reason']}")
    lines = [f"freeze: {'n/a' if res.get('na') else 'ok' if res['ok'] else 'RED'} — {res['reason']}"]
    for r in res["entries"]:
        if r["ok"]:
            lines.append(f"  ✓ {r['id']}: {r['note']}")
        else:
            lines += [f"  ✗ {r['id']}: {p}" for p in r["problems"]]
    return "\n".join(_clean(ln) for ln in lines)
